import { useState, useEffect } from 'react';
import api from '../services/api';
import { useAuth } from '../context/AuthContext';
import { fmtRON } from '../utils';

export default function CNAS() {
  const { user } = useAuth();
  const [dosare, setDosare] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    api.get('/cnas/dosare', { params: user.id_farmacie ? { id_farmacie: user.id_farmacie } : {} })
      .then(r => setDosare(r.data.data || []))
      .catch(err => setError(err.response?.data?.message || 'Nu am putut încărca dosarele CNAS.'))
      .finally(() => setLoading(false));
  }, [user.id_farmacie]);

  if (loading) return <div className="empty-state"><div className="spin">⚕️</div><p>Se încarcă dosarele CNAS...</p></div>;
  if (error) return <div className="empty-state"><p>{error}</p></div>;

  return (
    <div className="tcard">
      <div className="tcard-head"><h3>🏥 Raportare CNAS</h3></div>
      <div style={{ overflowX: 'auto' }}>
        <table className="tbl">
          <thead><tr><th>Farmacie</th><th>Lună</th><th>An</th><th>Nr. rețete</th><th>Compensată</th><th>Coplata</th><th>Status</th></tr></thead>
          <tbody>
            {dosare.length === 0 ? (
              <tr><td colSpan={7} style={{ textAlign: 'center', padding: 20 }}>Nu există dosare CNAS încă.</td></tr>
            ) : dosare.map(d => (
              <tr key={`${d.id_farmacie}-${d.luna}-${d.an}`}>
                <td>{d.farmacie}</td>
                <td>{d.luna}</td>
                <td>{d.an}</td>
                <td>{d.nr_retete}</td>
                <td>{fmtRON(d.valoare_compensata)}</td>
                <td>{fmtRON(d.valoare_coplata)}</td>
                <td><span className={`badge ${d.status === 'GENERAT' ? 'b-green' : 'b-amber'}`}>{d.status}</span></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
